import sys

def main():
    c = int(sys.stdin.readline().strip())
    paragraph = sys.stdin.readline().rstrip('\n')

    if c == 1:
        words = paragraph.split()
        print(len(words))
    elif c == 2:
        result = []
        for i, char in enumerate(paragraph):
            if i == 0:
                result.append(char.upper())
            elif char == '.' and i + 1 < len(paragraph) and paragraph[i + 1] == ' ':
                result.append(char)
            elif char == ' ' and i + 1 < len(paragraph) and paragraph[i + 1] == '.':
                result.append(char)
            else:
                result.append(char)

        result_str = ''.join(result)
        sentences = result_str.split('. ')
        capitalized = []
        for sent in sentences:
            if sent and len(sent) > 0:
                first_char = sent[0]
                if first_char != ' ':
                    capitalized.append(first_char.upper() + sent[1:])
                else:
                    j = 0
                    while j < len(sent) and sent[j] == ' ':
                        j += 1
                    if j < len(sent):
                        capitalized.append(sent[:j] + sent[j].upper() + sent[j+1:])
                    else:
                        capitalized.append(sent)
            else:
                capitalized.append(sent)

        final_result = '. '.join(capitalized)
        print(final_result)
    elif c == 3:
        line3 = sys.stdin.readline().split()
        if len(line3) >= 2:
            old_word = line3[0]
            new_word = line3[1]
            words = paragraph.split()
            replaced = [new_word if word == old_word else word for word in words]
            print(' '.join(replaced))

if __name__ == "__main__":
    main()
